<script setup>
import {ref,reactive,computed,watch,onUnmounted} from 'vue';import {useRoute} from 'vue-router';import {Eye,Download,Check,X,RefreshCw,ArrowUpRight} from 'lucide-vue-next';import {api,download,preview} from '../lib/api';import {currency,dateText,label} from '../lib/format';import {notify} from '../lib/ui';import StatePanel from '../components/StatePanel.vue';import StatusBadge from '../components/StatusBadge.vue';import AppModal from '../components/AppModal.vue';
const route=useRoute(),payments=computed(()=>route.path.endsWith('payments')),rows=ref([]),loading=ref(true),error=ref(''),page=ref(1),status=ref('pending'),modal=ref(''),chosen=ref(null),modalError=ref(''),busy=ref(false),proofUrl=ref(''),proofType=ref(''),proofLoading=ref(false),note=ref(''),approved=ref(false);let sequence=0;
const base=computed(()=>payments.value?'/admin/payments':'/admin/identity-documents');function filePath(row){return payments.value?`/payments/${row.payment_id}/proof`:`/identity-documents/${row.document_id}/file`;}
async function load(){const seq=++sequence;loading.value=true;error.value='';try{const q=new URLSearchParams({page:page.value,limit:15});if(status.value)q.set('status',status.value);const result=await api(base.value+'?'+q);if(seq===sequence)rows.value=result.data;}catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)loading.value=false;}}
function release(){if(proofUrl.value)URL.revokeObjectURL(proofUrl.value);proofUrl.value='';}
function close(){if(busy.value)return;modal.value='';release();}
async function open(row,kind){chosen.value=row;modal.value=kind;modalError.value='';note.value='';approved.value=false;release();if(kind==='preview'){proofLoading.value=true;try{const blob=await api(filePath(row),{blob:true});if(modal.value==='preview'&&chosen.value===row){proofType.value=blob.type;proofUrl.value=URL.createObjectURL(blob);}}catch(e){modalError.value=e.message;}finally{proofLoading.value=false;}}}
async function save(){busy.value=true;modalError.value='';try{const row=chosen.value;if(payments.value){if(modal.value==='refund'){if(!approved.value)throw Error('กรุณายืนยันว่าได้คืนเงินจริงแล้ว');await api(`/admin/payments/${row.payment_id}/refund`,{method:'PATCH',body:{note:note.value}});}else await api(`/admin/payments/${row.payment_id}/verify`,{method:'PATCH',body:{status:modal.value==='approve'?'successful':'failed',note:note.value}});}else await api(`/admin/identity-documents/${row.document_id}/review`,{method:'PATCH',body:{status:modal.value==='approve'?'approved':'rejected',note:note.value}});notify('บันทึกผลเรียบร้อย');modal.value='';release();await load();}catch(e){modalError.value=e.message;}finally{busy.value=false;}}
async function saveProof(){try{await download(filePath(chosen.value),'proof'+(proofType.value==='application/pdf'?'.pdf':proofType.value==='image/png'?'.png':'.jpg'));}catch(e){modalError.value=e.message;}}
watch(()=>route.path,()=>{status.value='pending';page.value=1;close();load();},{immediate:true});onUnmounted(release);
</script>
<template><section class="admin-page"><div class="page-heading"><div><p class="eyebrow">{{ payments?'PAYMENT VERIFICATION':'GUEST VERIFICATION' }}</p><h1>{{ payments?'ตรวจการชำระเงิน':'ตรวจเอกสารผู้เข้าพัก' }}</h1><p class="muted">{{ payments?'ตรวจหลักฐานและยอดเงิน ก่อนยืนยันการชำระ':'ตรวจเอกสารยืนยันตัวตนก่อนอนุญาตให้เข้าพัก' }}</p></div><button class="btn outline" @click="load"><RefreshCw :size="17"/> โหลดใหม่</button></div><div class="panel"><div class="filter-bar"><label>สถานะ<select v-model="status" @change="page=1;load()"><option value="">ทั้งหมด</option><option value="pending">รอตรวจสอบ</option><template v-if="payments"><option value="successful">ชำระสำเร็จ</option><option value="failed">ไม่ผ่าน</option><option value="refunded">คืนเงินแล้ว</option></template><template v-else><option value="approved">อนุมัติ</option><option value="rejected">ไม่ผ่าน</option></template></select></label><span class="muted">หน้า {{ page }} · {{ rows.length }} รายการ</span></div><StatePanel :loading="loading" :error="error" :empty="!loading&&!error&&!rows.length" @retry="load"/><div v-if="!loading&&!error&&rows.length" class="table-wrap"><table><thead><tr><th>การจอง / รายการ</th><th>{{ payments?'จำนวนเงิน':'ประเภทเอกสาร' }}</th><th>{{ payments?'วิธีชำระ':'วันที่ส่ง' }}</th><th>สถานะ</th><th>ดำเนินการ</th></tr></thead><tbody><tr v-for="row in rows" :key="row.payment_id||row.document_id"><td><RouterLink :to="'/bookings/'+row.booking_id" class="table-link">{{ row.booking_number }} <ArrowUpRight :size="13"/></RouterLink><small>{{ row.payment_number||'เอกสาร #'+row.document_id }}</small><small v-if="row.reference_number">อ้างอิง {{ row.reference_number }}</small><small v-if="row.review_note||row.note">{{ row.review_note||row.note }}</small></td><td><strong>{{ payments?currency(row.amount):label(row.document_type) }}</strong></td><td>{{ payments?label(row.payment_method):dateText(row.uploaded_at) }}</td><td><StatusBadge :value="row.payment_status||row.document_status"/></td><td><div class="button-row"><button v-if="!payments||row.payment_method!=='cash'" class="icon-btn" aria-label="เปิดหลักฐาน" @click="open(row,'preview')"><Eye :size="17"/></button><template v-if="(row.payment_status||row.document_status)==='pending'"><button class="btn tiny primary" @click="open(row,'approve')"><Check :size="14"/> อนุมัติ</button><button class="btn tiny danger-outline" @click="open(row,'reject')"><X :size="14"/> ไม่ผ่าน</button></template><button v-if="row.payment_status==='successful'" class="btn tiny outline" @click="open(row,'refund')">บันทึกคืนเงิน</button></div></td></tr></tbody></table></div><div class="pagination"><button class="btn outline tiny" :disabled="page===1||loading" @click="page--;load()">ก่อนหน้า</button><span>หน้า {{ page }}</span><button class="btn outline tiny" :disabled="rows.length<15||loading" @click="page++;load()">ถัดไป</button></div></div><AppModal v-if="modal" :title="modal==='preview'?'ดูหลักฐาน':modal==='refund'?'บันทึกคืนเงินเต็มจำนวน':modal==='approve'?'ยืนยันการอนุมัติ':'ไม่อนุมัติรายการ'" :wide="modal==='preview'" @close="close"><div v-if="modalError" class="alert danger" role="alert">{{ modalError }}</div><template v-if="modal==='preview'"><StatePanel :loading="proofLoading"/><template v-if="proofUrl"><iframe v-if="proofType==='application/pdf'" :src="proofUrl" title="หลักฐาน PDF" class="proof-frame"/><img v-else :src="proofUrl" alt="หลักฐานที่ผู้เข้าพักส่ง" class="proof-image"/><div class="modal-actions"><button class="btn outline" @click="saveProof"><Download :size="16"/> ดาวน์โหลด</button></div></template></template><form v-else @submit.prevent="save"><p>การจอง <strong>{{ chosen.booking_number }}</strong></p><p v-if="payments">จำนวนเงิน <strong>{{ currency(chosen.amount) }}</strong></p><div v-if="modal==='refund'" class="alert info">โปรดคืนเงินจริงให้ลูกค้าก่อน ระบบนี้บันทึกสถานะคืนเงินเท่านั้น</div><div v-else-if="modal==='approve'" class="alert info">{{ payments?'อนุมัติเมื่อยอดเงินและบัญชีผู้รับตรงกับหลักฐานที่ตรวจแล้ว ระบบจะออกใบเสร็จ':'อนุมัติเมื่อเอกสารถูกต้องและตรงกับข้อมูลผู้เข้าพัก' }}</div><label>หมายเหตุ<textarea v-model="note" rows="3" maxlength="1000" :required="modal==='refund'||modal==='reject'"/></label><label v-if="modal==='refund'" class="check-label"><input type="checkbox" v-model="approved" required/> คืนเงินเต็มจำนวนให้ลูกค้าแล้ว</label><div class="modal-actions"><button type="button" class="btn outline" :disabled="busy" @click="close">กลับ</button><button class="btn" :class="modal==='reject'?'danger':'primary'" :disabled="busy">{{ busy?'กำลังบันทึก…':'ยืนยัน' }}</button></div></form></AppModal></section></template>
